// Runtime application identity, build stamp, and dev-worktree slots.
using System.Globalization;
using System.Reflection;
using System.Text.RegularExpressions;
using AntiNotepad.Theme;
using Avalonia.Media;

namespace AntiNotepad;

/// <summary>Runtime product identity sourced from the assembly attributes generated by AppInfo.props.</summary>
public static class AppInfo
{
    /// <summary>Identity, default shortcuts, and color for one development worktree slot.</summary>
    internal readonly record struct DevSlot(string Name, string ShowHideHotkey, string NewNoteHotkey, Color Color);

    private static readonly Assembly Assembly = typeof(AppInfo).Assembly;
    private static readonly string _informationalVersion =
        Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
        ?? throw new InvalidOperationException("AppInfo.props must define the informational version.");
    private static readonly string _name = GetName();
    private static readonly bool _isDevBuild = bool.TryParse(GetMetadata("AntiNotepadDev"), out var isDevBuild) && isDevBuild;
    private static string? _activeSlotName;
    private static readonly IReadOnlyList<DevSlot> _devSlots = Array.AsReadOnly(new[]
    {
        new DevSlot("Blue", "Ctrl+Alt+Shift+1", "Ctrl+Alt+Shift+F1", DevSlotTokens.Blue),
        new DevSlot("Red", "Ctrl+Alt+Shift+2", "Ctrl+Alt+Shift+F2", DevSlotTokens.Red),
        new DevSlot("Green", "Ctrl+Alt+Shift+3", "Ctrl+Alt+Shift+F3", DevSlotTokens.Green),
        new DevSlot("Purple", "Ctrl+Alt+Shift+4", "Ctrl+Alt+Shift+F4", DevSlotTokens.Purple),
        new DevSlot("Orange", "Ctrl+Alt+Shift+5", "Ctrl+Alt+Shift+F5", DevSlotTokens.Orange),
        new DevSlot("Silver", "Ctrl+Alt+Shift+6", "Ctrl+Alt+Shift+F6", DevSlotTokens.Silver),
    });

    private static string GetName()
    {
        var name = GetMetadata("AppName") ?? Assembly.GetCustomAttribute<AssemblyProductAttribute>()?.Product ?? Assembly.GetName().Name;
        return !string.IsNullOrWhiteSpace(name) ? name : throw new InvalidOperationException("AppInfo.props must define the product name.");
    }

    private static string? GetMetadata(string key) => Assembly.GetCustomAttributes<AssemblyMetadataAttribute>()
        .FirstOrDefault(attribute => attribute.Key == key)?.Value;

    public static string Name => _name;
    public static bool IsDevBuild => _isDevBuild;
    public static string? BuildBranch => GetMetadata("AntiNotepadBranch") is { Length: > 0 } branch ? branch : null;
    public static DateTimeOffset? BuildTime => DateTimeOffset.TryParseExact(GetMetadata("AntiNotepadBuildTime"), "o",
        CultureInfo.InvariantCulture, DateTimeStyles.None, out var time) ? time : null;

    internal static IReadOnlyList<DevSlot> DevSlots => _devSlots;
    internal static string? SlotName => ResolveSlotName(Environment.GetEnvironmentVariable(Env("SLOT")));
    internal static string? ActiveSlotName => _activeSlotName;
    internal static Color? SlotColor => GetDevSlot(_activeSlotName)?.Color;

    /// <summary>Stores the slot selected by Program after it confirms custom data is present.</summary>
    internal static void SetActiveSlotName(string? name) => _activeSlotName = ResolveSlotName(name);

    /// <summary>The branch symbol that opens the dev badge; drawn from Cascadia, with a text fallback.</summary>
    internal const string DevBadgeGlyph = "\uE0A0";

    /// <summary>Formats the branch and build time shown by the dev badge.</summary>
    internal static (string Short, string Full) FormatDevBadge(string? branch, DateTimeOffset? time)
    {
        if (time is null) return ("dev", "dev");

        const string glyph = DevBadgeGlyph;
        var shortTime = time.Value.ToString("h:mm", CultureInfo.InvariantCulture);
        var fullTime = time.Value.ToString("h:mm tt", CultureInfo.InvariantCulture);
        if (string.IsNullOrWhiteSpace(branch) || branch == "(detached HEAD)")
            return ($"{glyph} {shortTime}", $"{glyph} {fullTime} (detached HEAD)");
        if (branch == "dev") return ($"{glyph} dev", $"{glyph} dev - {fullTime}");

        var slug = Regex.Replace(branch, @"^[A-Za-z]+/", "");
        var match = Regex.Match(slug, @"^[A-Za-z]+[0-9]+[A-Za-z]?");
        if (!match.Success)
            return ($"{glyph} {slug[..Math.Min(12, slug.Length)]}-{shortTime}", $"{glyph} {slug} - {fullTime}");

        var id = match.Value;
        var name = slug[id.Length..].TrimStart('-');
        return ($"{glyph} {id}-{shortTime}", $"{glyph} {id}{(name.Length == 0 ? "" : $" - {name}")} - {fullTime}");
    }

    /// <summary>Returns the canonical slot name only for one of the six assigned colors.</summary>
    internal static string? ResolveSlotName(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return null;
        foreach (var slot in _devSlots)
            if (string.Equals(slot.Name, name.Trim(), StringComparison.OrdinalIgnoreCase)) return slot.Name;
        return null;
    }

    /// <summary>Returns the matching slot's identity, or null when the name is not assigned.</summary>
    internal static string? DevInstanceIdForSlot(string? name) =>
        GetDevSlot(name) is { } slot ? $"{DevInstanceId}-{slot.Name.ToLowerInvariant()}" : null;

    /// <summary>Selects the installed or isolated dev identity, honoring slots only for a custom data folder.</summary>
    internal static string ResolveInstanceId(string? customDataFolder, string? slotName)
    {
        if (customDataFolder is not { Length: > 0 }) return InstanceId;
        return DevInstanceIdForSlot(slotName) ?? DevInstanceId;
    }

    /// <summary>Selects the icon resource for the build identity and optional dev slot.</summary>
    internal static string ResolveIconUri(bool isDevBuild, string? slotName)
    {
        var file = !isDevBuild
            ? "antinotepad.ico"
            : GetDevSlot(slotName) is { } slot
                ? $"antinotepad-dev-{slot.Name.ToLowerInvariant()}.ico"
                : "antinotepad-dev.ico";
        return $"avares://{Name}/{file}";
    }

    private static DevSlot? GetDevSlot(string? name)
    {
        var canonical = ResolveSlotName(name);
        if (canonical is null) return null;
        foreach (var slot in _devSlots)
            if (slot.Name == canonical) return slot;
        return null;
    }

    public static string DisplayName => IsDevBuild ? $"{Name} (dev)" : Name;

    public static string InformationalVersion => _informationalVersion;

    public static string Version
    {
        get
        {
            var separator = _informationalVersion.IndexOfAny(['-', '+']);
            return separator < 0 ? _informationalVersion : _informationalVersion[..separator];
        }
    }

    public static string Label
    {
        get
        {
            var start = _informationalVersion.IndexOf('-');
            if (start < 0) return "";
            var end = _informationalVersion.IndexOf('+', start + 1);
            return end < 0 ? _informationalVersion[(start + 1)..] : _informationalVersion[(start + 1)..end];
        }
    }

    public static string Description => Assembly.GetCustomAttribute<AssemblyDescriptionAttribute>()?.Description
        ?? throw new InvalidOperationException("AppInfo.props must define the description.");
    public static string Copyright => Assembly.GetCustomAttribute<AssemblyCopyrightAttribute>()?.Copyright
        ?? throw new InvalidOperationException("AppInfo.props must define the copyright.");

    public static string InstanceId => Name;
    public static string DevInstanceId => $"{Name}-dev";
    public static string DataFolderName => Name;
    public static string RunValueName => Name;
    public static string LogFileName => $"{Name.ToLowerInvariant()}.log";
    public static string EnvPrefix => Name.ToUpperInvariant();
    public static string IconUri => ResolveIconUri(IsDevBuild, _activeSlotName);
    public static string FontUri => $"avares://{Name}/Assets/Fonts/FluentSystemIcons-Regular.ttf";
    public static string ResourceUri => $"avares://{Name}/";

    public static string Env(string suffix)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(suffix);
        return $"{EnvPrefix}_{suffix.Trim().ToUpperInvariant()}";
    }
}
